import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen2Test {

    private GenericMaster genericMaster;

    @Before
    public void setUp() {
        genericMaster = new GenericMaster();
    }





    @Test
    public void testGetGenericType_ParameterizedTypeWithClassArgument() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType mockedType = mock(ParameterizedType.class);

        // Simulate List<String> where index [1] is String.class
        // Note: The code accesses index [1], so we need an array of size 2
        Type[] typeArguments = new Type[]{String.class, String.class};

        when(field.getGenericType()).thenReturn(mockedType);
        when(mockedType.getActualTypeArguments()).thenReturn(typeArguments);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(String.class, result);
    }




}

package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen2Test {

    private GenericMaster genericMaster;

    @Before
    public void setUp() {
        genericMaster = new GenericMaster();
    }







    @Test
    public void testGetGenericType_ParameterizedTypeWithNestedParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType outerType = mock(ParameterizedType.class);
        ParameterizedType innerType = mock(ParameterizedType.class);

        // Simulate Map<String, List<Integer>>
        // index [1] is List<Integer> (a ParameterizedType)
        Type[] outerTypeArguments = new Type[]{String.class, innerType};

        when(field.getGenericType()).thenReturn(outerType);
        when(outerType.getActualTypeArguments()).thenReturn(outerTypeArguments);
        when(innerType.getRawType()).thenReturn(java.util.List.class);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(java.util.List.class, result);
    }


}

